// ─── Endocrinology Calculators ───────────────────────────────────────────────

function EndoInputRow({ label, value, onChange, placeholder, unit, optional }) {
  return (
    <div>
      <label style={{ fontSize: 12, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", display: "block", marginBottom: 6 }}>
        {label} <span style={{ fontWeight: 400, textTransform: "none", letterSpacing: 0, fontSize: 11 }}>({unit || "mmol/L"}{optional ? " — optional" : ""})</span>
      </label>
      <input type="number" value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder}
        style={{ width: "100%", padding: "10px 12px", border: "1px solid var(--border)", borderRadius: 8, fontSize: 15, fontFamily: "Sora, sans-serif", fontWeight: 600, color: "var(--text-primary)", background: "var(--bg)", boxSizing: "border-box" }} />
    </div>
  );
}

function SerumOsmolalityTab({ C }) {
  const [na, setNa] = useState("");
  const [glucose, setGlucose] = useState("");
  const [urea, setUrea] = useState("");

  const naV = parseFloat(na);
  const gluV = parseFloat(glucose);
  const ureV = parseFloat(urea);
  const valid = !isNaN(naV) && !isNaN(gluV) && naV > 0 && gluV > 0;
  const hasUrea = urea !== "" && !isNaN(ureV) && ureV >= 0;

  const gluMgdl = gluV * 18;
  const multiplier = gluMgdl > 400 ? 2.4 : 1.6;
  const correctedNa = valid ? naV + ((gluMgdl - 100) / 100) * multiplier : null;
  const osmolality = valid && hasUrea ? 2 * naV + gluV + ureV : null;

  let osmInterp = null;
  if (osmolality !== null) {
    if (osmolality >= 320) osmInterp = { label: "HHS range (≥320 mOsm/kg)", color: "#7b341e", bg: "#fff5f0", border: "#fbd38d", icon: "⚠", detail: "Meets osmolality threshold for HHS. Some sources define HHS as >350 mOsm/kg — clinical context and glucose level are key." };
    else if (osmolality > 310) osmInterp = { label: "Hyperosmolar (>310 mOsm/kg)", color: "#744210", bg: "#fffff0", border: "#f6e05e", icon: "⚠", detail: "Hyperosmolar but below HHS diagnostic threshold. Monitor closely and treat underlying cause." };
    else if (osmolality >= 285) osmInterp = { label: "Normal range (285–310 mOsm/kg)", color: "#166534", bg: "#f0fff4", border: "#bbf7d0", icon: "✓", detail: "Plasma osmolality within normal limits." };
    else osmInterp = { label: "Low (<285 mOsm/kg)", color: "#1e40af", bg: "#f0f7ff", border: "#bfdbfe", icon: "ℹ", detail: "Hypoosmolar. Consider SIADH, dilutional hyponatraemia, or overhydration." };
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ padding: "9px 12px", background: "#f0f7ff", border: "1px solid #bfdbfe", borderRadius: 8, fontSize: 13, color: "#1e40af", lineHeight: 1.5 }}>
        ℹ Corrected Na uses the Hillier formula (×1.6 if glucose &lt;400 mg/dL; ×2.4 if ≥400 mg/dL). Serum osmolality = 2×Na + Glucose + Urea (SI units). Add urea to calculate osmolality.
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        <EndoInputRow label="Measured Sodium" value={na} onChange={setNa} placeholder="e.g. 128" />
        <EndoInputRow label="Blood Glucose" value={glucose} onChange={setGlucose} placeholder="e.g. 22" />
        <EndoInputRow label="Urea" value={urea} onChange={setUrea} placeholder="e.g. 8" optional />
      </div>
      {valid && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Results</div>
          <div style={{ padding: "10px 14px", background: "#eef6ff", border: `1px solid ${C}`, borderRadius: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <div style={{ fontSize: 12, color: "var(--text-muted)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Corrected Sodium</div>
              <div style={{ fontSize: 11.5, color: "var(--text-muted)", marginTop: 2 }}>Glucose {gluMgdl.toFixed(0)} mg/dL — using ×{multiplier} correction</div>
            </div>
            <div style={{ fontSize: 22, fontWeight: 700, color: C, fontFamily: "Sora, sans-serif", flexShrink: 0, marginLeft: 12 }}>
              {correctedNa != null ? `${(Math.round(correctedNa * 10) / 10)} mmol/L` : "—"}
            </div>
          </div>
          {hasUrea && osmolality !== null && (
            <div style={{ padding: "10px 14px", background: "var(--bg)", border: "1px solid var(--border)", borderRadius: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <div style={{ fontSize: 12, color: "var(--text-muted)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Calculated Osmolality</div>
                <div style={{ fontSize: 11.5, color: "var(--text-muted)", marginTop: 2 }}>2×Na + Glucose + Urea (SI units)</div>
              </div>
              <div style={{ fontSize: 22, fontWeight: 700, color: C, fontFamily: "Sora, sans-serif", flexShrink: 0, marginLeft: 12 }}>
                {Math.round(osmolality)} mOsm/kg
              </div>
            </div>
          )}
          {osmInterp && hasUrea && (
            <div style={{ padding: "10px 14px", background: osmInterp.bg, border: `1px solid ${osmInterp.border}`, borderRadius: 8, color: osmInterp.color }}>
              <div style={{ fontWeight: 700, fontSize: 14, fontFamily: "Sora, sans-serif", marginBottom: 4 }}>{osmInterp.icon} {osmInterp.label}</div>
              <div style={{ fontSize: 13, lineHeight: 1.5 }}>{osmInterp.detail}</div>
            </div>
          )}
          <div style={{ padding: "9px 12px", background: "var(--surface)", border: "1px solid var(--border)", borderRadius: 8, fontSize: 12.5, color: "var(--text-muted)", lineHeight: 1.6 }}>
            <strong>Reference:</strong> Normal osmolality ~290 mOsm/kg · Hyperosmolar &gt;310 · HHS ≥320 (some sources &gt;350)
          </div>
        </div>
      )}
    </div>
  );
}

function FurstFormulaTab({ C }) {
  const [urineNa, setUrineNa] = useState("");
  const [urineK, setUrineK] = useState("");
  const [serumNa, setSerumNa] = useState("");

  const uNaV = parseFloat(urineNa);
  const uKV = parseFloat(urineK);
  const sNaV = parseFloat(serumNa);
  const valid = !isNaN(uNaV) && !isNaN(uKV) && !isNaN(sNaV) && sNaV > 0;

  const ratio = valid ? (uNaV + uKV) / sNaV : null;

  let interp = null;
  if (ratio !== null) {
    if (ratio < 0.5) interp = { label: "< 0.5 — Commence 1 litre fluid restriction", color: "#166534", bg: "#f0fff4", border: "#bbf7d0", icon: "✓", detail: "Urine electrolyte concentration is low relative to serum — free water excretion likely. A 1 litre/day fluid restriction is recommended." };
    else if (ratio <= 1.0) interp = { label: "0.5–1.0 — Commence 500 ml fluid restriction", color: "#744210", bg: "#fffff0", border: "#f6e05e", icon: "⚠", detail: "Urine electrolyte concentration approaches serum — moderate fluid restriction of 500 ml/day is recommended." };
    else interp = { label: "> 1.0 — Fluid restriction not advised", color: "#7b341e", bg: "#fff5f0", border: "#fbd38d", icon: "✗", detail: "Urine electrolyte concentration exceeds serum — fluid restriction will not correct hyponatraemia and may be harmful. Consider alternative management." };
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ padding: "9px 12px", background: "#f0f7ff", border: "1px solid #bfdbfe", borderRadius: 8, fontSize: 13, color: "#1e40af", lineHeight: 1.5 }}>
        ℹ The Furst formula guides fluid restriction in hyponatraemia. Obtain a spot urine sample (Na⁺ + K⁺) alongside a serum Na⁺. Formula: (Urine Na⁺ + Urine K⁺) ÷ Serum Na⁺
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        <EndoInputRow label="Urine Sodium (Na⁺)" value={urineNa} onChange={setUrineNa} placeholder="e.g. 55" />
        <EndoInputRow label="Urine Potassium (K⁺)" value={urineK} onChange={setUrineK} placeholder="e.g. 30" />
        <EndoInputRow label="Serum Sodium (Na⁺)" value={serumNa} onChange={setSerumNa} placeholder="e.g. 128" />
      </div>
      {valid && ratio !== null && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Result</div>
          <div style={{ padding: "10px 14px", background: "#eef6ff", border: `1px solid ${C}`, borderRadius: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <div>
              <div style={{ fontSize: 12, color: "var(--text-muted)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Furst Ratio</div>
              <div style={{ fontSize: 11.5, color: "var(--text-muted)", marginTop: 2 }}>(Urine Na⁺ + Urine K⁺) ÷ Serum Na⁺</div>
            </div>
            <div style={{ fontSize: 22, fontWeight: 700, color: C, fontFamily: "Sora, sans-serif" }}>
              {ratio.toFixed(2)}
            </div>
          </div>
          {interp && (
            <div style={{ padding: "10px 14px", background: interp.bg, border: `1px solid ${interp.border}`, borderRadius: 8, color: interp.color }}>
              <div style={{ fontWeight: 700, fontSize: 14, fontFamily: "Sora, sans-serif", marginBottom: 4 }}>{interp.icon} {interp.label}</div>
              <div style={{ fontSize: 13, lineHeight: 1.5 }}>{interp.detail}</div>
            </div>
          )}
          <div style={{ padding: "9px 12px", background: "var(--surface)", border: "1px solid var(--border)", borderRadius: 8, fontSize: 12.5, color: "var(--text-muted)", lineHeight: 1.6 }}>
            <strong>Reference:</strong> &lt;0.5 → 1L restriction · 0.5–1.0 → 500ml restriction · &gt;1.0 → fluid restriction not advised
          </div>
        </div>
      )}
    </div>
  );
}

function EndocrinologyCalculator() {
  const C = "#2563a8";
  const [tab, setTab] = useState("osmolality");
  const tabs = [
    { id: "osmolality", label: "Serum Osmolality" },
    { id: "furst", label: "Furst Formula" },
  ];
  return (
    <div>
      <div style={{ display: "flex", gap: 0, marginBottom: 20, borderBottom: "2px solid var(--border)" }}>
        {tabs.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)}
            style={{ padding: "9px 18px", border: "none", background: "none", cursor: "pointer", fontFamily: "Sora, sans-serif", fontSize: 13, fontWeight: 600, color: tab === t.id ? C : "var(--text-muted)", borderBottom: `2px solid ${tab === t.id ? C : "transparent"}`, marginBottom: -2, transition: "color 0.15s" }}>
            {t.label}
          </button>
        ))}
      </div>
      {tab === "osmolality" && <SerumOsmolalityTab C={C} />}
      {tab === "furst" && <FurstFormulaTab C={C} />}
    </div>
  );
}

function CalculatorView({ calcId, onNavigate }) {
  const calc = CALCULATORS[calcId];
  if (!calc) return null;
  const site = SITES.find(s => s.id === calc.siteId);

 const checkColors = {
  question: { bg: "#f0f7ff", border: "#bfdbfe", color: "#1e40af", icon: "?" },
  warning: { bg: "#fffbeb", border: "#fde68a", color: "#92400e", icon: "⚠" },
  info: { bg: "#f0fff4", border: "#bbf7d0", color: "#166534", icon: "ℹ" },
};

return (
  <div style={{ maxWidth: 720 }}>
    <div style={{ display: "flex", alignItems: "center", marginBottom: 4 }}>
      <button className="detail-back-btn" onClick={() => onNavigate({ type: "calculators" })}>
        <IconArrowLeft />
        Back to Calculators
      </button>
      {calc.guidelineId && (() => {
        const linkedG = findGuideline(calc.guidelineId);
        const linkedSite = SITES.find(s => s.id === linkedG?.siteId);
        return linkedG ? (
          <button className="detail-back-btn"
            onClick={() => onNavigate({ type: "guideline", guidelineId: calc.guidelineId })}
            style={{ marginLeft: 16, color: linkedSite?.color }}
          >
            <IconExternal /> View {linkedG.title} guideline
          </button>
        ) : null;
      })()}
    </div>

    {/* Header */}
      <div style={{ marginBottom: 24 }}>
        <div className="detail-category-badge" style={{ background: site?.accent || "#f0f0f0", color: site?.color || "#555" }}>
          <span style={{ fontSize: 14 }}>{calc.icon}</span>
          {site?.label || "Calculator"}
        </div>
        <h1 className="detail-title">{calc.label}</h1>
      </div>

      {/* When to use */}
      <div className="detail-card" style={{ marginBottom: 14 }}>
        <h3 style={{ marginBottom: 12 }}>{calc.whenToUse.headline}</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {calc.whenToUse.checks.map((check, i) => {
            const c = checkColors[check.type];
            return (
              <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "9px 12px", background: c.bg, border: `1px solid ${c.border}`, borderRadius: 8 }}>
                <span style={{ width: 20, height: 20, borderRadius: "50%", background: c.border, color: c.color, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, flexShrink: 0, marginTop: 1 }}>{c.icon}</span>
                <p style={{ fontSize: 13.5, color: c.color, lineHeight: 1.55, margin: 0 }}>{check.text}</p>
              </div>
            );
          })}
        </div>
      </div>

      {/* Calculator */}
      <div className="detail-card">
        <h3 style={{ marginBottom: 14 }}>Calculator</h3>
        {calc.component === "irae" && <IraeGradeCalculator siteColor={site?.color || "#6d4c9e"} siteAccent={site?.accent || "#f3effe"} />}
        {calc.component === "antibiotic-dosing" && (<AntibioticDosingCalculator />)}
        {calc.component === "mascc" && <MasccCalculator />}
        {calc.component === "opioid-converter" && <OpioidConverter />}
        {calc.component === "sins" && <SinsCalculator />}
        {calc.component === "endocrinology" && <EndocrinologyCalculator />}
      {calc.component === "hfa-icos" && (
  <div style={{ padding: "12px", background: "var(--bg)", borderRadius: 8, border: "1px solid var(--border)" }}>
    <p style={{ fontSize: 13.5, color: "var(--text-secondary)", marginBottom: 12 }}>The HFA-ICOS tool is an externally validated risk calculator hosted on MDCalc:</p>
    <a href="https://www.mdcalc.com/calc/10642/hfa-icos-baseline-cardio-oncology-risk-assessment-anthracycline-chemotherapy"
      target="_blank" rel="noopener noreferrer"
      className="detail-btn detail-btn-primary" style={{ display: "inline-flex" }}>
      <IconExternal /> Open HFA-ICOS Calculator on MDCalc
    </a>
  </div>
)}
      </div>
    </div>
  );
}


function OpioidConverter() {
  const C = "#4a7c6b";
  const [drug, setDrug] = useState("morphine-po");
  const [dose, setDose] = useState("");

  const conversions = {
    "codeine-po":        { label: "Codeine PO",          toMorphinePO: 1/10 },
    "dihydrocodeine-po": { label: "Dihydrocodeine PO",   toMorphinePO: 1/10 },
    "tramadol-po":       { label: "Tramadol PO",         toMorphinePO: 1/10 },
    "morphine-po":       { label: "Morphine PO",         toMorphinePO: 1 },
    "oxycodone-po":      { label: "Oxycodone PO",        toMorphinePO: 1.5 },
  };

  const d = parseFloat(dose);
  const valid = !isNaN(d) && d > 0;
  const morphinePO = valid ? d * (conversions[drug]?.toMorphinePO || 1) : null;

  const fentanylTable = [[30,12],[60,25],[120,50],[180,75],[240,100]];
  const bupTable      = [[12,5],[24,10],[48,20],[84,35],[126,52.5],[168,70]];

  function getPatch(table, val) {
    for (let i = table.length - 1; i >= 0; i--) {
      if (val >= table[i][0]) return table[i][1];
    }
    return table[0][1];
  }

  const fentPatch      = morphinePO ? getPatch(fentanylTable, morphinePO) : null;
  const bupPatch       = morphinePO ? getPatch(bupTable, morphinePO) : null;
  const diamorphineSC  = morphinePO ? morphinePO / 3 : null;
  const morphineSC     = morphinePO ? morphinePO / 2 : null;
  const fentanylSC     = morphinePO ? morphinePO * 6.25 : null;   // mcg: 4mg PO → 25mcg SC
  const alfentanilSC   = morphinePO ? morphinePO * 31.25 : null;  // mcg: 4mg PO → 125mcg SC
  const oxycodoneSC    = morphinePO ? morphinePO / 4 : null;      // mg: 4mg PO → 1mg SC
  const btMin          = morphinePO ? morphinePO / 10 : null;
  const btMax          = morphinePO ? morphinePO / 6 : null;

  const R = ({ label, value, unit, note, highlight }) => (
    <div style={{ padding: "10px 14px", background: highlight ? "#eaf3f0" : "var(--bg)", border: `1px solid ${highlight ? C : "var(--border)"}`, borderRadius: 8, display: "flex", justifyContent: "space-between", alignItems: "center", textAlign: "left" }}>
      <div style={{ textAlign: "left" }}>
        <div style={{ fontSize: 12, color: "var(--text-muted)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>{label}</div>
        {note && <div style={{ fontSize: 11.5, color: "var(--text-muted)", marginTop: 2, lineHeight: 1.4 }}>{note}</div>}
      </div>
      <div style={{ fontSize: 18, fontWeight: 700, color: C, fontFamily: "Sora, sans-serif", flexShrink: 0, marginLeft: 12 }}>
        {value != null ? `${Math.round(value * 10) / 10}${unit ? " " + unit : ""}` : "—"}
      </div>
    </div>
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12, textAlign: "left" }}>
      <div style={{ padding: "10px 14px", background: "#fffbeb", border: "1px solid #f6d860", borderRadius: 8, fontSize: 13, color: "#92700a", lineHeight: 1.5 }}>
        ⚠ Always reduce by 25–50% when switching opioids (incomplete cross-tolerance). Reduce by 50% at high doses, in elderly/frail, or after rapid escalation. Verify with PCF or palliative care team.
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        <div>
          <label style={{ fontSize: 12, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", display: "block", marginBottom: 6 }}>Current opioid</label>
          <select value={drug} onChange={e => setDrug(e.target.value)}
            style={{ width: "100%", padding: "10px 12px", border: "1px solid var(--border)", borderRadius: 8, fontSize: 14, background: "var(--bg)", color: "var(--text-primary)", fontFamily: "DM Sans, sans-serif" }}>
            {Object.entries(conversions).map(([k,v]) => <option key={k} value={k}>{v.label}</option>)}
          </select>
        </div>
        <div>
          <label style={{ fontSize: 12, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", display: "block", marginBottom: 6 }}>Total 24-hour dose (mg)</label>
          <input type="number" value={dose} onChange={e => setDose(e.target.value)} placeholder="e.g. 60"
            style={{ width: "100%", padding: "10px 12px", border: `1px solid ${valid ? C : "var(--border)"}`, borderRadius: 8, fontSize: 16, fontFamily: "Sora, sans-serif", fontWeight: 700, color: C, background: "var(--bg)", boxSizing: "border-box" }} />
        </div>
      </div>
      {valid && (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif" }}>Oral equivalences</div>
          <R label="Morphine PO /24h" value={morphinePO} unit="mg" highlight />
          <R label="Breakthrough dose" value={btMin} unit={`– ${Math.round(btMax*10)/10} mg`} note="1/10 to 1/6 of 24h morphine PO — every 2–4h PRN" />
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", marginTop: 4 }}>SC conversions</div>
          <R label="Diamorphine SC /24h" value={diamorphineSC} unit="mg" note="÷ 3 from morphine PO" />
          <R label="Morphine SC /24h" value={morphineSC} unit="mg" note="÷ 2 from morphine PO" />
          <R label="Fentanyl SC /24h" value={fentanylSC} unit="mcg" note="÷ 160 from morphine PO (mcg). Preferred in renal failure" highlight />
          <R label="Alfentanil SC /24h" value={alfentanilSC} unit="mcg" note="÷ 32 from morphine PO (mcg). Use in renal failure when fentanyl unavailable" />
          <R label="Oxycodone SC /24h" value={oxycodoneSC} unit="mg" note="÷ 4 from morphine PO. Caution: accumulation risk in renal failure" />
          <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", marginTop: 4 }}>Transdermal equivalents</div>
          <R label="Fentanyl patch" value={fentPatch} unit="mcg/h" note="72h patch — nearest standard dose. Ratio 100:1 (morphine PO : fentanyl TD)" />
          <R label="Buprenorphine patch" value={bupPatch} unit="mcg/h" note="Nearest standard dose. Ratio 100:1 (morphine PO : buprenorphine TD)" />
          <div style={{ padding: "9px 12px", background: "#fff5f5", border: "1px solid #fc8181", borderRadius: 8, fontSize: 12.5, color: "#742a2a", lineHeight: 1.5 }}>
            ⚡ Patches contraindicated for acute pain (effect takes &gt;12h). Always prescribe PRN medication alongside patches. Verify at high doses with PCF or palliative care team.
          </div>
        </div>
      )}

      {/* Renal failure CSCI reference table */}
      <div style={{ marginTop: 4 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-muted)", textTransform: "uppercase", letterSpacing: "0.05em", fontFamily: "Sora, sans-serif", marginBottom: 8 }}>Renal Failure — CSCI Starting Doses</div>
        <div style={{ padding: "9px 12px", background: "#fffbeb", border: "1px solid #fde68a", borderRadius: 8, fontSize: 12.5, color: "#92700a", lineHeight: 1.5, marginBottom: 8 }}>
          ⚠ Do <strong>not</strong> use morphine or diamorphine in continuous infusion in renal failure — high risk of accumulation and adverse effects.
        </div>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5, textAlign: "left", border: "1px solid var(--border)", borderRadius: 8, overflow: "hidden" }}>
            <thead>
              <tr style={{ background: C, color: "white" }}>
                {["Oral Morphine", "Fentanyl SC", "Alfentanil SC", "Oxycodone SC"].map(h => (
                  <th key={h} style={{ padding: "7px 10px", fontFamily: "Sora, sans-serif", fontSize: 11, fontWeight: 700, letterSpacing: "0.03em" }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[
                ["4 mg", "25 mcg", "125 mcg", "1 mg"],
                ["8 mg", "50 mcg", "250 mcg", "2 mg"],
                ["CSCI starting doses", "100–200 mcg / 24h", "500 mcg – 1 mg / 24h", "4–8 mg / 24h"],
              ].map((row, ri) => (
                <tr key={ri} style={{ background: ri % 2 === 0 ? "var(--surface)" : "var(--bg)", borderTop: "1px solid var(--border-light)" }}>
                  {row.map((cell, ci) => (
                    <td key={ci} style={{ padding: "7px 10px", fontWeight: ri === 2 && ci === 0 ? 600 : 400, color: ri === 2 && ci === 0 ? "var(--text-primary)" : "var(--text-secondary)", fontStyle: ri === 2 && ci === 0 ? "italic" : "normal", fontSize: ri === 2 && ci === 0 ? 11.5 : 12.5 }}>{cell}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p style={{ fontSize: 11.5, color: "var(--text-muted)", marginTop: 6, lineHeight: 1.5 }}>Single PRN dose = 1/10th to 1/6th of 24h CSCI dose. Most patients with renal failure require only low doses — if dose is escalating, seek palliative care advice.</p>
      </div>
    </div>
  );
}

function CalculatorsPage({ onNavigate }) {
  return (
    <div>
      <div className="home-greeting">
        <h1>Clinical Calculators</h1>
        <p>Interactive decision-support tools for NUH Acute Oncology</p>
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {Object.values(CALCULATORS).map(calc => {
          const site = SITES.find(s => s.id === calc.siteId);
          return (
            <div key={calc.id}
              onClick={() => onNavigate({ type: "calculator", calcId: calc.id })}
              style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 16px", background: "var(--surface)", border: "1px solid var(--border)", borderRadius: 10, cursor: "pointer", transition: "all 0.15s" }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = site?.color || "var(--accent)"; e.currentTarget.style.boxShadow = "var(--shadow-sm)"; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = "var(--border)"; e.currentTarget.style.boxShadow = "none"; }}
            >
              <div style={{ width: 44, height: 44, borderRadius: 10, background: site?.accent || "#f0f0f0", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20, flexShrink: 0 }}>{calc.icon}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14, fontFamily: "Sora, sans-serif", color: "var(--text-primary)", marginBottom: 2 }}>{calc.label}</div>
                <div style={{ fontSize: 12.5, color: "var(--text-muted)" }}>{site?.label} · {calc.whenToUse.checks.length} clinical considerations</div>
              </div>
              <span style={{ color: "var(--text-muted)" }}><IconChevronRight /></span>
            </div>
          );
        })}
      </div>
    </div>
  );
}


