// ── STYLES ────────────────────────────────────────────────────────────────────


const css = `
  @import url('https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700&family=DM+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg: #f7f8fa;
    --surface: #ffffff;
    --border: #e4e8ed;
    --border-light: #eff1f5;
    --text-primary: #0f1923;
    --text-secondary: #5a6474;
    --text-muted: #9ba3af;
    --accent: #1a6b8a;
    --accent-light: #e8f4f8;
    --accent-hover: #145773;
    --sidebar-width: 268px;
    --shadow-sm: 0 1px 3px rgba(15,25,35,0.06), 0 1px 2px rgba(15,25,35,0.04);
    --shadow-md: 0 4px 12px rgba(15,25,35,0.08), 0 2px 4px rgba(15,25,35,0.04);
    --shadow-lg: 0 12px 32px rgba(15,25,35,0.10), 0 4px 8px rgba(15,25,35,0.05);
    --radius: 10px;
    --radius-sm: 6px;
    --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  }

  body { font-family: 'DM Sans', sans-serif; background: var(--bg); color: var(--text-primary); line-height: 1.6; }
  h1,h2,h3,h4,h5 { font-family: 'Sora', sans-serif; }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 5px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 99px; }

  /* Layout */
  .app { display: flex; height: 100vh; overflow: hidden; }

  /* Sidebar */
  .sidebar {
    width: var(--sidebar-width);
    min-width: var(--sidebar-width);
    background: var(--surface);
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    transition: width var(--transition), min-width var(--transition), transform var(--transition);
    overflow: hidden;
    z-index: 100;
  }
  .sidebar.collapsed { width: 0; min-width: 0; border-right: none; }
  .sidebar.floating {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    box-shadow: var(--shadow-lg);
  }
  .sidebar-header {
    padding: 16px 16px 16px;
    border-bottom: 1px solid var(--border-light);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
  }
  .sidebar-logo {
    display: flex;
    align-items: center;
    gap: 8px;
    font-family: 'Sora', sans-serif;
    font-weight: 600;
    font-size: 13px;
    color: var(--text-primary);
    letter-spacing: -0.01em;
  }
  .sidebar-logo-dot {
    width: 26px; height: 26px;
    background: linear-gradient(135deg, var(--accent) 0%, #2a9bc4 100%);
    border-radius: 7px;
    display: flex; align-items: center; justify-content: center;
    color: white;
    font-size: 11px; font-weight: 700; font-family: 'Sora', sans-serif;
  }


  .sidebar-content { flex: 1; overflow-y: auto; padding: 8px 8px 16px; }

  .sidebar-section { margin-bottom: 4px; }
  .sidebar-section-header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 6px 8px;
    cursor: pointer;
    border-radius: var(--radius-sm);
    transition: background var(--transition);
    user-select: none;
  }
  .sidebar-section-header:hover { background: var(--bg); }
  .sidebar-section-title {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-muted);
    font-family: 'Sora', sans-serif;
  }
  .sidebar-section-body { overflow: hidden; }

  .sidebar-item {
    display: flex; align-items: center; gap: 8px;
    padding: 6px 10px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-size: 13px;
    color: var(--text-secondary);
    transition: all var(--transition);
    text-decoration: none;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    touch-action: manipulation;
  }
  .sidebar-item:hover { background: var(--bg); color: var(--text-primary); }
  .sidebar-item.active { background: var(--accent-light); color: var(--accent); font-weight: 500; }
  .sidebar-item-icon { flex-shrink: 0; opacity: 0.7; }
  .sidebar-sub-item {
    padding: 5px 10px 5px 28px;
    font-size: 12.5px;
  }

  .site-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
  }

  .sidebar-divider { height: 1px; background: var(--border-light); margin: 8px 8px; }

  /* Main */
  .main {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
  }

  /* Topbar */
  .topbar {
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 12px 24px;
    display: flex;
    align-items: center;
    gap: 12px;
    flex-shrink: 0;
  }
  .topbar-menu-btn {
    width: 34px; height: 34px;
    border: 1px solid var(--border);
    background: var(--bg);
    border-radius: var(--radius-sm);
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    color: var(--text-secondary);
    transition: all var(--transition);
    flex-shrink: 0;
  }
  .topbar-menu-btn:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-light); }
  .topbar-fav-btn { position: relative; color: var(--text-muted); }
  .topbar-fav-btn:hover { color: #f59e0b; border-color: #f6d860; background: #fef9e7; }
  .topbar-fav-btn.active { color: #f59e0b; border-color: #f6d860; background: #fef9e7; }
  .topbar-fav-badge {
    position: absolute;
    top: -5px; right: -5px;
    min-width: 16px; height: 16px;
    background: #f59e0b;
    color: white;
    border-radius: 99px;
    font-size: 9px;
    font-weight: 700;
    font-family: 'Sora', sans-serif;
    display: flex; align-items: center; justify-content: center;
    padding: 0 3px;
    line-height: 1;
  }

  .topbar-breadcrumb {
    display: flex; align-items: center; gap: 6px;
    font-size: 13px;
    color: var(--text-muted);
  }
  .topbar-breadcrumb span { color: var(--text-primary); font-weight: 500; }
  .topbar-breadcrumb a { color: var(--text-muted); cursor: pointer; text-decoration: none; transition: color var(--transition); }
  .topbar-breadcrumb a:hover { color: var(--accent); }

  /* Breadcrumb row sits below the topbar, on every screen size */
  .topbar-breadcrumb-row {
    padding: 8px 24px;
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    overflow-x: auto;
    white-space: nowrap;
    flex-shrink: 0;
  }

  /* Mobile-only topbar controls (back/home) */
  .mobile-only-btn { display: none; }

  /* Print button on the breadcrumb row — pinned far right, hidden on mobile */
  .breadcrumb-print-btn {
    display: inline-flex; align-items: center; gap: 6px;
    margin-left: auto;
    padding: 5px 12px;
    border: 1px solid var(--border);
    border-radius: 99px;
    background: var(--bg);
    color: var(--text-secondary);
    font-size: 12.5px;
    font-family: 'DM Sans', sans-serif;
    cursor: pointer;
    flex-shrink: 0;
    transition: all var(--transition);
  }
  .breadcrumb-print-btn:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-light); }

  .search-wrap {
    position: relative;
    flex-shrink: 0;
    margin-left: auto;
  }
  .search-input {
    width: 220px;
    padding: 7px 12px 7px 34px;
    border: 1px solid var(--border);
    border-radius: 99px;
    font-size: 13px;
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    color: var(--text-primary);
    transition: all var(--transition);
    outline: none;
  }
  .search-input:focus { border-color: var(--accent); background: white; box-shadow: 0 0 0 3px rgba(26,107,138,0.08); width: 280px; }
  .search-input::placeholder { color: var(--text-muted); }
  .search-icon { position: absolute; left: 11px; top: 50%; transform: translateY(-50%); color: var(--text-muted); pointer-events: none; }

  /* Content */
  .content { flex: 1; overflow-y: auto; padding: 28px 32px; text-align: left; }

  /* Homepage */
  .home-greeting {
    margin-bottom: 28px;
  }
  .home-greeting h1 {
    font-size: 22px;
    font-weight: 600;
    letter-spacing: -0.02em;
    color: var(--text-primary);
    margin-bottom: 4px;
  }
  .home-greeting p { font-size: 14px; color: var(--text-muted); }

  .home-section-title {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--text-muted);
    font-family: 'Sora', sans-serif;
    margin-bottom: 12px;
  }

  .sites-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
    gap: 14px;
    margin-bottom: 32px;
  }
  .site-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 20px;
    cursor: pointer;
    transition: all var(--transition);
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .site-card:hover { border-color: var(--site-color, var(--accent)); box-shadow: var(--shadow-md); transform: translateY(-1px); }
  .site-card-icon {
    width: 44px; height: 44px;
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    background: var(--site-accent, var(--accent-light));
    color: var(--site-color, var(--accent));
  }
  .site-card-name {
    font-size: 14px; font-weight: 600;
    font-family: 'Sora', sans-serif;
    color: var(--text-primary);
    letter-spacing: -0.01em;
  }
  .site-card-count { font-size: 12px; color: var(--text-muted); }
  .site-card-preview {
    display: flex; flex-direction: column; gap: 3px;
    margin-top: 4px;
  }
  .site-card-preview-item {
    font-size: 11.5px;
    color: var(--text-secondary);
    display: flex; align-items: center; gap: 6px;
  }
  .site-card-preview-item::before {
    content: '';
    width: 4px; height: 4px;
    border-radius: 50%;
    background: var(--site-color, var(--accent));
    opacity: 0.5;
    flex-shrink: 0;
  }

  /* Favourites */
  .favourites-section { margin-bottom: 32px; }
  .favourites-grid {
    display: flex; flex-wrap: wrap; gap: 8px;
  }
  .fav-chip {
    display: flex; align-items: center; gap: 6px;
    padding: 6px 12px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 99px;
    font-size: 12.5px;
    cursor: pointer;
    transition: all var(--transition);
    color: var(--text-secondary);
  }
  .fav-chip:hover { border-color: var(--site-color, var(--accent)); color: var(--site-color, var(--accent)); background: var(--site-accent, var(--accent-light)); }
  .fav-chip-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
  .fav-empty {
    font-size: 13px;
    color: var(--text-muted);
    font-style: italic;
    padding: 4px 0;
  }

  /* Site view */
  .site-header {
    display: flex; align-items: center; gap: 14px;
    margin-bottom: 24px;
    padding-bottom: 20px;
    border-bottom: 1px solid var(--border-light);
  }
  .site-header-icon {
    width: 48px; height: 48px;
    border-radius: 12px;
    display: flex; align-items: center; justify-content: center;
  }
  .site-header-info h2 {
    font-size: 20px; font-weight: 600;
    letter-spacing: -0.02em;
    margin-bottom: 2px;
  }
  .site-header-info p { font-size: 13px; color: var(--text-muted); }

  .guidelines-list { display: flex; flex-direction: column; gap: 2px; }
  .guideline-category {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.07em;
    text-transform: uppercase;
    color: var(--text-muted);
    font-family: 'Sora', sans-serif;
    padding: 16px 0 6px;
  }
  .guideline-row {
    display: flex; align-items: center; gap: 12px;
    padding: 12px 14px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: all var(--transition);
    border: 1px solid transparent;
    background: var(--surface);
    margin-bottom: 3px;
  }
  .guideline-row:hover { border-color: var(--border); box-shadow: var(--shadow-sm); background: var(--surface); }
  .guideline-row-content { flex: 1; min-width: 0; }
  .guideline-row-title {
    font-size: 13.5px; font-weight: 500;
    color: var(--text-primary);
    margin-bottom: 2px;
    font-family: 'Sora', sans-serif;
  }
  .guideline-row-summary {
    font-size: 12px;
    color: var(--text-muted);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .guideline-row-meta {
    display: flex; align-items: center; gap: 8px;
    flex-shrink: 0;
  }
  .guideline-row-updated {
    font-size: 11px;
    color: var(--text-muted);
  }
  .star-btn {
    width: 28px; height: 28px;
    border: none; background: transparent;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    color: var(--text-muted);
    border-radius: var(--radius-sm);
    transition: all var(--transition);
    flex-shrink: 0;
  }
  .star-btn:hover { color: #f59e0b; background: #fef3c7; }
  .star-btn.starred { color: #f59e0b; }
  .tags-row { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
  .tag {
    padding: 2px 8px;
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 99px;
    font-size: 11px;
    color: var(--text-secondary);
  }

  /* Guideline detail */
  .guideline-detail { max-width: 760px; text-align: left; }
  .detail-header {
    margin-bottom: 24px;
    text-align: left;
  }
  .detail-back-btn {
    display: inline-flex; align-items: center; gap: 6px;
    font-size: 12.5px;
    color: var(--text-muted);
    cursor: pointer;
    border: none; background: none;
    padding: 4px 0;
    margin-bottom: 12px;
    transition: color var(--transition);
    font-family: 'DM Sans', sans-serif;
  }
  .detail-back-btn:hover { color: var(--accent); }
  .detail-title {
    font-size: 22px;
    font-weight: 600;
    letter-spacing: -0.02em;
    margin-bottom: 4px;
    color: var(--text-primary);
  }
  .detail-category-badge {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 3px 10px;
    border-radius: 99px;
    font-size: 11.5px;
    font-weight: 500;
    margin-bottom: 8px;
  }
  .detail-meta { font-size: 12px; color: var(--text-muted); margin-bottom: 16px; }

  .detail-meta-table { width: 100%; border-collapse: collapse; font-size: 12px; margin-bottom: 16px; border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
  .detail-meta-table tr { border-bottom: 1px solid var(--border); }
  .detail-meta-table tr:last-child { border-bottom: none; }
  .detail-meta-table td { padding: 6px 10px; vertical-align: top; color: var(--text-secondary); line-height: 1.5; }
  .detail-meta-table td.dmt-label { width: 108px; min-width: 108px; color: var(--text-muted); font-weight: 500; white-space: nowrap; border-right: 1px solid var(--border); }
  .dmt-links { display: flex; flex-direction: column; gap: 4px; }
  .dmt-link-row { font-size: 12px; }
  .dmt-link-row a { display: inline-flex; align-items: center; gap: 5px; color: var(--accent); text-decoration: none; font-weight: 500; }
  .dmt-link-row a:hover { text-decoration: underline; }
  .review-badge { display: inline-flex; align-items: center; padding: 2px 8px; border-radius: 99px; font-size: 11.5px; font-weight: 500; }
  .review-badge-future { background: #e8f5ee; color: #1a7a4c; border: 1px solid #b7e0c8; }
  .review-badge-soon { background: #fff6dd; color: #92660a; border: 1px solid #f0d98c; }
  .review-badge-past { background: #fdecea; color: #b3261e; border: 1px solid #f3b7b0; }

  .detail-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    padding: 22px 24px;
    margin-bottom: 14px;
    text-align: left;
  }
  .detail-card h3 {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-muted);
    font-family: 'Sora', sans-serif;
    margin-bottom: 10px;
  }
  /* Section header bar — matches the "Steroid protocol by presentation" treatment:
     pastel blue background, dark blue text, bled out to the card's edges. Scoped to
     direct-child h3s only, so cards with their own custom header bar (already
     nested in an inner div) or semantic alert colors are unaffected. */
  .detail-card > h3 {
    font-weight: 700;
    color: #1a6b8a;
    background: #e8f4f8;
    margin: -22px -24px 14px -24px;
    padding: 11px 24px;
    border-radius: var(--radius) var(--radius) 0 0;
  }
  .detail-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.7; }

  .detail-actions {
    display: flex; gap: 10px;
    flex-wrap: wrap;
  }
  .detail-btn {
    display: inline-flex; align-items: center; gap: 7px;
    padding: 9px 16px;
    border-radius: var(--radius-sm);
    font-size: 13px;
    font-weight: 500;
    font-family: 'DM Sans', sans-serif;
    cursor: pointer;
    transition: all var(--transition);
    text-decoration: none;
    border: 1px solid var(--border);
  }
  .detail-btn-primary {
    background: var(--accent);
    color: white;
    border-color: var(--accent);
  }
  .detail-btn-primary:hover { background: var(--accent-hover); }
  .detail-btn-secondary {
    background: var(--surface);
    color: var(--text-secondary);
  }
  .detail-btn-secondary:hover { border-color: var(--accent); color: var(--accent); background: var(--accent-light); }

  .related-list { display: flex; flex-direction: column; gap: 6px; }
  .related-item {
    display: flex; align-items: center; justify-content: space-between;
    padding: 9px 12px;
    border-radius: var(--radius-sm);
    border: 1px solid var(--border-light);
    cursor: pointer;
    transition: all var(--transition);
    background: var(--bg);
  }
  .related-item:hover { border-color: var(--border); background: var(--surface); box-shadow: var(--shadow-sm); }
  .related-item-info {}
  .related-item-title { font-size: 13px; font-weight: 500; color: var(--text-primary); font-family: 'Sora', sans-serif; }
  .related-item-site { font-size: 11.5px; color: var(--text-muted); margin-top: 1px; }

  /* Search results */
  .search-results-header {
    font-size: 13px; color: var(--text-muted);
    margin-bottom: 16px;
  }
  .search-results-header strong { color: var(--text-primary); }

  /* Guideline pill grid */
  .guideline-pills-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-bottom: 4px;
  }
  .guideline-pill {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 11px 13px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    cursor: pointer;
    transition: all var(--transition);
    text-align: left;
    min-width: 0;
    position: relative;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }
  .guideline-pill:hover { border-color: var(--pill-color, var(--accent)); box-shadow: var(--shadow-sm); }
  .guideline-pill.stub { opacity: 0.45; cursor: default; }
  .guideline-pill-title {
    font-size: 13px;
    font-weight: 500;
    color: var(--text-primary);
    font-family: "Sora", sans-serif;
    line-height: 1.35;
    flex: 1;
    min-width: 0;
  }
  .guideline-pill-badge { font-size: 10px; padding: 1px 6px; background: #f1f1f1; border: 1px solid #ddd; border-radius: 99px; color: #aaa; font-weight: 500; flex-shrink: 0; }
  .guideline-pill-star { opacity: 0; flex-shrink: 0; transition: opacity 0.15s; }
  .guideline-pill:hover .guideline-pill-star { opacity: 1; }
  .guideline-pill-star.starred { opacity: 1; }
  @media (max-width: 600px) { .guideline-pills-grid { grid-template-columns: 1fr; } }

  /* Summary callout */
  .summary-callout {
    background: var(--surface);
    border: 1px solid var(--callout-color, var(--accent));
    border-radius: var(--radius);
    padding: 13px 16px;
    margin-bottom: 14px;
  }
  .summary-callout ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 7px; }
  .summary-callout li { display: flex; align-items: flex-start; gap: 9px; font-size: 13.5px; color: var(--text-secondary); line-height: 1.5; }
  .summary-callout-dot { width: 5px; height: 5px; border-radius: 50%; flex-shrink: 0; margin-top: 7px; }

  /* Structured management group */
  .mgmt-group { margin-bottom: 12px; }
  .mgmt-group:last-child { margin-bottom: 0; }
  .mgmt-group-header { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; padding-bottom: 4px; border-bottom: 1px solid var(--border-light); }
  .mgmt-group-label { font-size: 10.5px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; font-family: "Sora", sans-serif; color: var(--text-muted); }

  /* Overlay for floating sidebar */
  .sidebar-overlay {
    position: fixed;
    inset: 0;
    background: rgba(15,25,35,0.15);
    z-index: 99;
    backdrop-filter: blur(1px);
  }

  /* Empty state */
  .empty-state {
    text-align: center;
    padding: 48px 24px;
    color: var(--text-muted);
  }
  .empty-state p { font-size: 14px; margin-top: 8px; }

  /* Mobile */
  @media (max-width: 768px) {
    .sidebar {
      position: absolute;
      left: 0; top: 0; bottom: 0;
      box-shadow: var(--shadow-lg);
      z-index: 200;
    }
    .sidebar.collapsed { width: 0; min-width: 0; box-shadow: none; }
    .content { padding: 16px; }
    .topbar { padding: 10px 14px; }
    .mobile-only-btn { display: flex; }
    .topbar-breadcrumb-row { padding: 8px 14px; }
    .breadcrumb-print-btn { display: none; }
    .search-input { width: 140px; }
    .search-input:focus { width: 180px; }
    .sites-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .guideline-detail { max-width: 100%; }
    .detail-actions { flex-direction: column; }
    .detail-btn { justify-content: center; }

    /* Criteria table (e.g. Neutropenic Sepsis) — shrink text so columns stay readable */
    .criteria-intro-text { font-size: 12px !important; }
    .criteria-subheading { font-size: 10.5px !important; }
    .criteria-footer-label { font-size: 10px !important; }
    .criteria-tablewrap th { font-size: 9.5px !important; padding: 6px 5px !important; }
    .criteria-tablewrap td { padding: 7px 5px !important; }
    .criteria-tablewrap td, .criteria-tablewrap li { font-size: 11px !important; }
  }
  .preview-badge {
    display: inline-flex; align-items: center; gap: 5px;
    padding: 3px 9px;
    background: #fff8e1;
    border: 1px solid #f6d860;
    border-radius: 99px;
    font-size: 11px;
    color: #92700a;
    font-weight: 500;
    font-family: 'Sora', sans-serif;
    margin-left: 8px;
  }

  /* Print — show only the guideline content, no app chrome */
  @media print {
    .sidebar, .topbar, .topbar-breadcrumb-row, .detail-back-btn, .detail-actions, .sidebar-overlay {
      display: none !important;
    }
    .app, .main, .content { display: block; height: auto; overflow: visible; }
    .content { padding: 0; }
    .guideline-detail { max-width: 100%; }
  }
`;

